// Exact quartic certificate: products.
#include "field_qq.hpp"
#include <array>
using Mon=array<int,5>;using OP=map<Mon,Rat>;using M6=array<int,6>;using LP=map<M6,Rat>;
constexpr int NV=16;fmpq_mpoly_ctx_t c16;
void read16(istream&in,fmpq_mpoly_t x){long n;in>>n;assert(in);fmpq_mpoly_zero(x,c16);fmpq_t c;fmpq_init(c);ulong ex[NV];for(long i=0;i<n;i++){string s;in>>s;assert(fmpq_set_str(c,s.c_str(),10)==0);fmpq_canonicalise(c);for(auto&v:ex)in>>v;assert(in);if(ex[2]+ex[3]+ex[4]+ex[5]+ex[6]+ex[12]+ex[14]==0)fmpq_mpoly_push_term_fmpq_ui(x,c,ex,c16);}fmpq_mpoly_sort_terms(x,c16);fmpq_mpoly_combine_like_terms(x,c16);fmpq_clear(c);}
void write16(ostream&out,const fmpq_mpoly_t x){long n=fmpq_mpoly_length(x,c16);out<<n<<'\n';fmpq_t c;fmpq_init(c);ulong ex[NV];for(long i=0;i<n;i++){fmpq_mpoly_get_term_coeff_fmpq(c,x,i,c16);char*s=fmpq_get_str(nullptr,10,c);out<<s;flint_free(s);fmpq_mpoly_get_term_exp_ui(ex,x,i,c16);for(auto v:ex)out<<' '<<v;out<<'\n';}fmpq_clear(c);}
void lift2(fmpq_mpoly_t out,const fmpq_mpoly_t x,const Mon&m){fmpq_t c;fmpq_init(c);ulong a[2],ex[NV]{};for(int j=0;j<5;j++)ex[j+2]=m[j];for(long i=0;i<fmpq_mpoly_length(x,ctx);i++){fmpq_mpoly_get_term_coeff_fmpq(c,x,i,ctx);fmpq_mpoly_get_term_exp_ui(a,x,i,ctx);ex[0]=a[0];ex[1]=a[1];fmpq_mpoly_push_term_fmpq_ui(out,c,ex,c16);}fmpq_clear(c);}
int main(int argc,char**argv){fmpq_mpoly_ctx_init(ctx,2,ORD_LEX);fmpq_mpoly_ctx_init(c16,NV,ORD_LEX);flint_set_num_threads(2);{ifstream in(argv[1]),ii(argv[2]),rel(argv[3]);int n,ns,ni;in>>n>>ns;ii>>ni;assert(n==24&&ns==17&&ni==n);vector<Rat>contents(n);for(auto&v:contents)readpoly(in,v.n);vector<fmpq_mpoly_struct>ops(n*ns),W(ns);for(auto&v:ops){fmpq_mpoly_init(&v,c16);read16(in,&v);}for(auto&v:W){fmpq_mpoly_init(&v,c16);read16(in,&v);}Rat common;readpoly(in,common.n);
vector<vector<OP>> inv(n,vector<OP>(n));for(int j=0;j<n;j++)for(int i=0;i<n;i++){int l;ii>>l;for(int k=0;k<l;k++){Mon m;for(int&v:m)ii>>v;Rat x;readpoly(ii,x.n);readpoly(ii,x.d);x.reduce();x=divi(x,contents[i]);if(m==Mon{})inv[j][i].emplace(m,std::move(x));}}cerr<<"INVERSE LOADED\n";
int nr,nc;rel>>nr>>nc;map<int,Row>rr;for(int z=0;z<nr;z++){int id,l;rel>>id>>l;for(int k=0;k<l;k++){int j;rel>>j;Rat c;readpoly(rel,c.n);readpoly(rel,c.d);c.reduce();rr[id].emplace(j,std::move(c));}}
vector<int>selected;for(auto&[id,row]:rr)selected.push_back(id);ofstream out(argv[4]);assert(out);out<<selected.size()<<'\n';
for(int id:selected){vector<LP>coeff(n);for(auto&[source,c]:rr[id])if(source%9!=5&&source%9!=7)for(int i=0;i<n;i++)for(auto&[mon,b]:inv[source/9][i]){M6 m;for(int j=0;j<5;j++)m[j]=mon[j];m[5]=source%9;Rat v=mul(c,b);fmpq_mpoly_neg(v.n,v.n,ctx);Rat x=sub(coeff[i][m],v);if(x.zero())coeff[i].erase(m);else coeff[i][m]=std::move(x);}cerr<<"RELATION COMBINED "<<id<<'\n';
Rat den;fmpq_mpoly_one(den.n,ctx);fmpq_mpoly_t g,quot,tmp;for(auto p:{g,quot,tmp})fmpq_mpoly_init(p,ctx);for(auto&row:coeff)for(auto&[m,x]:row){assert(fmpq_mpoly_gcd(g,den.n,x.d,ctx));assert(fmpq_mpoly_divides(quot,x.d,g,ctx));fmpq_mpoly_mul(tmp,den.n,quot,ctx);fmpq_mpoly_swap(den.n,tmp,ctx);}
fmpq_mpoly_t C,P,A,D,G,num,de,shift,unreducedD;for(auto p:{C,P,A,D,G,num,de,shift,unreducedD})fmpq_mpoly_init(p,c16);vector<fmpq_mpoly_struct>cp(n),aa(ns);for(int i=0;i<n;i++){fmpq_mpoly_init(&cp[i],c16);for(auto&[m,x]:coeff[i]){assert(fmpq_mpoly_divides(quot,den.n,x.d,ctx));fmpq_mpoly_mul(tmp,quot,x.n,ctx);Mon nu;for(int j=0;j<5;j++)nu[j]=m[j];fmpq_mpoly_zero(shift,c16);lift2(shift,tmp,nu);fmpq_mpoly_sort_terms(shift,c16);fmpq_mpoly_combine_like_terms(shift,c16);fmpq_mpoly_gen(P,7+m[5],c16);fmpq_mpoly_mul(A,shift,P,c16);fmpq_mpoly_add(&cp[i],&cp[i],A,c16);}}
lift2(D,den.n,Mon{});fmpq_mpoly_sort_terms(D,c16);fmpq_mpoly_combine_like_terms(D,c16);fmpq_mpoly_set(G,D,c16);
for(int b=0;b<ns;b++){fmpq_mpoly_init(&aa[b],c16);for(int i=0;i<n;i++)if(!fmpq_mpoly_is_zero(&cp[i],c16)&&!fmpq_mpoly_is_zero(&ops[i*ns+b],c16)){fmpq_mpoly_mul(P,&cp[i],&ops[i*ns+b],c16);fmpq_mpoly_add(&aa[b],&aa[b],P,c16);}if(!fmpq_mpoly_is_zero(&aa[b],c16)){assert(fmpq_mpoly_gcd(A,G,&aa[b],c16));fmpq_mpoly_swap(G,A,c16);}}
assert(fmpq_mpoly_divides(de,D,G,c16));long opterms=0;for(int b=0;b<ns;b++){assert(fmpq_mpoly_divides(A,&aa[b],G,c16));opterms+=fmpq_mpoly_length(A,c16);fmpq_mpoly_mul(P,A,&W[b],c16);fmpq_mpoly_add(C,C,P,c16);}cerr<<"OPERATOR "<<id<<" TERMS "<<opterms<<'\n';fmpq_mpoly_zero(D,c16);lift2(D,common.n,Mon{});fmpq_mpoly_sort_terms(D,c16);fmpq_mpoly_combine_like_terms(D,c16);fmpq_mpoly_mul(unreducedD,D,de,c16);assert(fmpq_mpoly_gcd_cofactors(G,num,de,C,unreducedD,c16));out<<id<<'\n';write16(out,num);write16(out,de);cerr<<"QUARTIC "<<id<<" TERMS "<<fmpq_mpoly_length(num,c16)<<" / "<<fmpq_mpoly_length(de,c16)<<'\n';out.flush();for(auto&v:cp)fmpq_mpoly_clear(&v,c16);for(auto&v:aa)fmpq_mpoly_clear(&v,c16);for(auto p:{C,P,A,D,G,num,de,shift,unreducedD})fmpq_mpoly_clear(p,c16);for(auto p:{g,quot,tmp})fmpq_mpoly_clear(p,ctx);}
for(auto&v:ops)fmpq_mpoly_clear(&v,c16);for(auto&v:W)fmpq_mpoly_clear(&v,c16);}fmpq_mpoly_ctx_clear(c16);fmpq_mpoly_ctx_clear(ctx);flint_cleanup();}
